/* ==========================================================================
   Meu Segundo Cérebro — visual v2 ("app")
   Vale só para notas com `cssclasses: sc-app`.
   Os cartões são callouts nativos do Obsidian + 1 link interno real cada.
   ========================================================================== */

/* ---------- Cores (claro) ---------- */
body {
  --sc2-rosa: #fde2ea;    --sc2-rosa-t: #b8476f;
  --sc2-lilas: #e4e4fb;   --sc2-lilas-t: #5357b8;
  --sc2-pessego: #fee7d3; --sc2-pessego-t: #b0651c;
  --sc2-salvia: #e2eedd;  --sc2-salvia-t: #4b7a49;
  --sc2-menta: #d5f3e7;   --sc2-menta-t: #1f8263;
  --sc2-roxo: #ece3fa;    --sc2-roxo-t: #7244b5;
  --sc2-coral: #fde0d8;   --sc2-coral-t: #c15237;
  --sc2-ceu: #dcEEFB;     --sc2-ceu-t: #2f72a8;
  --sc2-amarelo: #fdf1c9; --sc2-amarelo-t: #9a7410;
  --sc2-raio: 20px;
}
/* ---------- Cores (escuro) ---------- */
body.theme-dark {
  --sc2-rosa: rgba(232, 120, 160, .17);    --sc2-rosa-t: #f4a3c1;
  --sc2-lilas: rgba(132, 136, 240, .18);   --sc2-lilas-t: #b0b2ff;
  --sc2-pessego: rgba(240, 160, 90, .17);  --sc2-pessego-t: #f5bf8a;
  --sc2-salvia: rgba(130, 180, 125, .17);  --sc2-salvia-t: #aed6a9;
  --sc2-menta: rgba(70, 195, 150, .17);    --sc2-menta-t: #86dfbd;
  --sc2-roxo: rgba(165, 120, 235, .19);    --sc2-roxo-t: #cbabf7;
  --sc2-coral: rgba(238, 125, 98, .18);    --sc2-coral-t: #f6ab95;
  --sc2-ceu: rgba(90, 160, 230, .18);      --sc2-ceu-t: #9fcaf2;
  --sc2-amarelo: rgba(230, 195, 80, .17);  --sc2-amarelo-t: #ecd283;
}

/* ---------- Página ---------- */
.sc-app { --file-line-width: 940px; }
.sc-app .inline-title,
.sc-app .metadata-container,
.sc-app .frontmatter-container,
.sc-app .embedded-backlinks { display: none; }

/* aviso que só aparece quando ESTE CSS está desligado */
.callout[data-callout="sc-aviso-css"] { display: none !important; }

/* todos os callouts do app: sem ícone, sem borda, sem azul padrão */
.sc-app .callout[data-callout^="sc-"] {
  border: 0;
  box-shadow: none;
  mix-blend-mode: normal;
  background: transparent;
  padding: 0;
  margin: 0;
}
.sc-app .callout[data-callout^="sc-"] > .callout-title .callout-icon,
.sc-app .callout[data-callout^="sc-"] > .callout-title .callout-fold { display: none; }

/* ---------- Topo ---------- */
.sc-app .callout[data-callout="sc-topo"] { margin: 4px 0 22px; }
.sc-app .callout[data-callout="sc-topo"] > .callout-title {
  font-size: 1.85em;
  font-weight: 800;
  line-height: 1.15;
  color: var(--text-normal);
  padding: 0;
}
.sc-app .callout[data-callout="sc-topo"] > .callout-content {
  padding: 4px 0 0;
  color: var(--text-muted);
  font-size: .98em;
}
.sc-app .callout[data-callout="sc-topo"] > .callout-content p { margin: 0; }
.sc-app .callout[data-callout="sc-topo"] a.internal-link {
  color: var(--text-muted);
  text-decoration: none;
  font-size: .9em;
}
.sc-app .callout[data-callout="sc-topo"] a.internal-link:hover { color: var(--text-normal); }

/* ---------- Grade de cartões ---------- */
.sc-app .callout[data-callout="sc-grade"] { margin: 0 0 28px; }
.sc-app .callout[data-callout="sc-grade"] > .callout-title { display: none; }
.sc-app .callout[data-callout="sc-grade"] > .callout-content {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 14px;
  padding: 0;
}
.sc-app .callout[data-callout="sc-grade-p"] { margin: 0 0 28px; }
.sc-app .callout[data-callout="sc-grade-p"] > .callout-title { display: none; }
.sc-app .callout[data-callout="sc-grade-p"] > .callout-content {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 12px;
  padding: 0;
}

/* ---------- Cartão ---------- */
.sc-app .callout[data-callout^="sc-c-"] {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 118px;
  padding: 16px 16px 14px;
  border-radius: var(--sc2-raio);
  background: var(--sc2-bg);
  transition: transform .12s ease, filter .12s ease;
}
.sc-app .callout[data-callout^="sc-c-"]:hover { transform: translateY(-2px); filter: saturate(1.08); }
.sc-app .callout[data-callout^="sc-c-"] > .callout-title {
  padding: 0;
  font-size: 2.1em;          /* o ícone */
  line-height: 1;
}
.sc-app .callout[data-callout^="sc-c-"] > .callout-content { padding: 0; }
.sc-app .callout[data-callout^="sc-c-"] > .callout-content p { margin: 12px 0 0; }
.sc-app .callout[data-callout^="sc-c-"] a.internal-link {
  color: var(--sc2-t);
  font-weight: 700;
  font-size: 1.05em;
  text-decoration: none;
}
/* o cartão inteiro abre a nota: a área do link cobre o cartão */
.sc-app .callout[data-callout^="sc-c-"] a.internal-link::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--sc2-raio);
  z-index: 2;
}
.sc-app .callout[data-callout="sc-grade-p"] .callout[data-callout^="sc-c-"] { min-height: 100px; padding: 14px; }
.sc-app .callout[data-callout="sc-grade-p"] .callout[data-callout^="sc-c-"] > .callout-title { font-size: 1.8em; }
.sc-app .callout[data-callout="sc-grade-p"] .callout[data-callout^="sc-c-"] a.internal-link { font-size: .98em; }

.callout[data-callout="sc-c-rosa"]    { --sc2-bg: var(--sc2-rosa);    --sc2-t: var(--sc2-rosa-t); }
.callout[data-callout="sc-c-lilas"]   { --sc2-bg: var(--sc2-lilas);   --sc2-t: var(--sc2-lilas-t); }
.callout[data-callout="sc-c-pessego"] { --sc2-bg: var(--sc2-pessego); --sc2-t: var(--sc2-pessego-t); }
.callout[data-callout="sc-c-salvia"]  { --sc2-bg: var(--sc2-salvia);  --sc2-t: var(--sc2-salvia-t); }
.callout[data-callout="sc-c-menta"]   { --sc2-bg: var(--sc2-menta);   --sc2-t: var(--sc2-menta-t); }
.callout[data-callout="sc-c-roxo"]    { --sc2-bg: var(--sc2-roxo);    --sc2-t: var(--sc2-roxo-t); }
.callout[data-callout="sc-c-coral"]   { --sc2-bg: var(--sc2-coral);   --sc2-t: var(--sc2-coral-t); }
.callout[data-callout="sc-c-ceu"]     { --sc2-bg: var(--sc2-ceu);     --sc2-t: var(--sc2-ceu-t); }
.callout[data-callout="sc-c-amarelo"] { --sc2-bg: var(--sc2-amarelo); --sc2-t: var(--sc2-amarelo-t); }

/* ---------- Painéis (títulos discretos + tabela do Bases arredondada) ---------- */
.sc-app h2 {
  font-size: .82em;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-muted);
  border: 0;
  margin: 26px 0 8px;
  padding: 0;
}
.sc-app .internal-embed:has(.bases-view),
.sc-app .bases-embed {
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  overflow: hidden;
  background: var(--background-primary);
}

/* ---------- iPhone ---------- */
@media (max-width: 600px) {
  .sc-app .callout[data-callout="sc-grade"] > .callout-content { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .sc-app .callout[data-callout="sc-grade-p"] > .callout-content { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .sc-app .callout[data-callout="sc-topo"] > .callout-title { font-size: 1.5em; }
  .sc-app .callout[data-callout^="sc-c-"] { min-height: 104px; }
}
.is-mobile .sc-app .callout[data-callout="sc-grade"] > .callout-content,
.is-mobile .sc-app .callout[data-callout="sc-grade-p"] > .callout-content { grid-template-columns: repeat(2, minmax(0, 1fr)); }


/* ===== v1 (áreas ainda não refeitas) ===== */
/* ==========================================================================
   Meu Segundo Cérebro — interface (snippet CSS)
   Só afeta notas com `cssclasses: sc-painel` e callouts cujo tipo começa com "sc-".
   Usa variáveis do Obsidian: funciona com o tema padrão, claro e escuro, Windows e iPhone.
   ========================================================================== */

/* ---------- Paleta (modo claro) ---------- */
body {
  --sc-vida-bg: #fbe4ec;         --sc-vida-ac: #c2577f;
  --sc-trabalho-bg: #e3e3fa;     --sc-trabalho-ac: #5c5fc4;
  --sc-projetos-bg: #fdebd3;     --sc-projetos-ac: #b8741f;
  --sc-conhecimento-bg: #e1ecdc; --sc-conhecimento-ac: #4f7d4e;
  --sc-financeiro-bg: #d8f2e6;   --sc-financeiro-ac: #23866a;
  --sc-planejamento-bg: #ebe2f7; --sc-planejamento-ac: #7448b8;
  --sc-entrada-bg: #fde0d7;      --sc-entrada-ac: #c9573c;
  --sc-cerebro-bg: linear-gradient(135deg, #fbe4ec 0%, #ebe2f7 45%, #e1ecdc 100%);
  --sc-raio: 16px;
  --sc-sombra: 0 1px 2px rgba(0, 0, 0, .05), 0 4px 14px rgba(0, 0, 0, .05);
}

/* ---------- Paleta (modo escuro) ---------- */
body.theme-dark {
  --sc-vida-bg: rgba(226, 120, 160, .16);         --sc-vida-ac: #f19bbd;
  --sc-trabalho-bg: rgba(130, 134, 235, .17);     --sc-trabalho-ac: #a9abff;
  --sc-projetos-bg: rgba(232, 168, 84, .16);      --sc-projetos-ac: #f2c07c;
  --sc-conhecimento-bg: rgba(126, 176, 124, .16); --sc-conhecimento-ac: #a6d3a2;
  --sc-financeiro-bg: rgba(72, 190, 150, .16);    --sc-financeiro-ac: #7fdcb9;
  --sc-planejamento-bg: rgba(160, 120, 230, .18); --sc-planejamento-ac: #c5a6f5;
  --sc-entrada-bg: rgba(236, 128, 100, .17);      --sc-entrada-ac: #f5a68f;
  --sc-cerebro-bg: linear-gradient(135deg, rgba(226,120,160,.20) 0%, rgba(160,120,230,.20) 50%, rgba(126,176,124,.18) 100%);
  --sc-sombra: none;
}

/* ---------- Página de painel ---------- */
.sc-painel {
  --file-line-width: 1080px;
}
.sc-painel .inline-title,
.sc-painel .metadata-container,
.sc-painel .frontmatter-container {
  display: none;
}
.sc-painel h2 {
  font-size: 1.15em;
  margin-top: 1.8em;
  padding-bottom: .3em;
  border-bottom: 2px solid var(--background-modifier-border);
}
.sc-painel h3 {
  font-size: 1em;
  color: var(--text-muted);
  margin-top: 1.2em;
}
.sc-painel p.sc-dica,
.sc-painel .sc-dica {
  color: var(--text-muted);
  font-size: .9em;
}

/* cor de destaque do título da página, por área */
.sc-painel.sc-vida h2 { border-color: var(--sc-vida-ac); }
.sc-painel.sc-trabalho h2 { border-color: var(--sc-trabalho-ac); }
.sc-painel.sc-projetos h2 { border-color: var(--sc-projetos-ac); }
.sc-painel.sc-conhecimento h2 { border-color: var(--sc-conhecimento-ac); }
.sc-painel.sc-financeiro h2 { border-color: var(--sc-financeiro-ac); }
.sc-painel.sc-planejamento h2 { border-color: var(--sc-planejamento-ac); }
.sc-painel.sc-entrada h2 { border-color: var(--sc-entrada-ac); }

/* ---------- Base de todos os callouts "sc-" ---------- */
.callout[data-callout^="sc-"] {
  --callout-padding: 14px 16px;
  border: none;
  border-radius: var(--sc-raio);
  background: var(--sc-bg, var(--background-secondary));
  box-shadow: var(--sc-sombra);
  mix-blend-mode: normal;
}
.callout[data-callout^="sc-"] > .callout-title .callout-icon { display: none; }
.callout[data-callout^="sc-"] > .callout-title {
  color: var(--text-normal);
  font-weight: 700;
  gap: 0;
}
.callout[data-callout^="sc-"] > .callout-content { color: var(--text-normal); }
.callout[data-callout^="sc-"] > .callout-content > p:last-child { margin-bottom: 0; }

/* ---------- Cabeçalho ---------- */
.callout[data-callout="sc-cabecalho"] {
  --sc-bg: var(--sc-cerebro-bg);
  padding: 26px 24px;
  text-align: center;
}
.callout[data-callout="sc-cabecalho"] > .callout-title {
  justify-content: center;
  font-size: 1.9em;
  line-height: 1.2;
}
.callout[data-callout="sc-cabecalho"] > .callout-content {
  color: var(--text-muted);
  font-size: 1.05em;
}

/* ---------- Grade de cartões ---------- */
.callout[data-callout="sc-grade"] {
  --sc-bg: transparent;
  box-shadow: none;
  padding: 0;
  margin: 1em 0;
}
.callout[data-callout="sc-grade"] > .callout-title { display: none; }
.callout[data-callout="sc-grade"] > .callout-content {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
  padding: 0;
}
.callout[data-callout="sc-grade"] > .callout-content > .callout { margin: 0; }

/* ---------- Cartões das áreas ---------- */
.callout[data-callout="sc-vida"]         { --sc-bg: var(--sc-vida-bg);         --sc-ac: var(--sc-vida-ac); }
.callout[data-callout="sc-trabalho"]     { --sc-bg: var(--sc-trabalho-bg);     --sc-ac: var(--sc-trabalho-ac); }
.callout[data-callout="sc-projetos"]     { --sc-bg: var(--sc-projetos-bg);     --sc-ac: var(--sc-projetos-ac); }
.callout[data-callout="sc-conhecimento"] { --sc-bg: var(--sc-conhecimento-bg); --sc-ac: var(--sc-conhecimento-ac); }
.callout[data-callout="sc-financeiro"]   { --sc-bg: var(--sc-financeiro-bg);   --sc-ac: var(--sc-financeiro-ac); }
.callout[data-callout="sc-planejamento"] { --sc-bg: var(--sc-planejamento-bg); --sc-ac: var(--sc-planejamento-ac); }
.callout[data-callout="sc-entrada"]      { --sc-bg: var(--sc-entrada-bg);      --sc-ac: var(--sc-entrada-ac); }

.callout[data-callout="sc-vida"], .callout[data-callout="sc-trabalho"],
.callout[data-callout="sc-projetos"], .callout[data-callout="sc-conhecimento"],
.callout[data-callout="sc-financeiro"], .callout[data-callout="sc-planejamento"],
.callout[data-callout="sc-entrada"] {
  position: relative;              /* o link do título cobre o cartão inteiro */
  min-height: 108px;
  border-left: 5px solid var(--sc-ac);
  transition: transform .12s ease, box-shadow .12s ease;
}
.callout[data-callout="sc-vida"]:hover, .callout[data-callout="sc-trabalho"]:hover,
.callout[data-callout="sc-projetos"]:hover, .callout[data-callout="sc-conhecimento"]:hover,
.callout[data-callout="sc-financeiro"]:hover, .callout[data-callout="sc-planejamento"]:hover,
.callout[data-callout="sc-entrada"]:hover {
  transform: translateY(-2px);
}
.callout[data-callout^="sc-"] > .callout-title a.internal-link {
  color: var(--text-normal);
  text-decoration: none;
  font-size: 1.12em;
}
/* torna o CARTÃO INTEIRO clicável: o "::after" do link cobre o cartão */
.callout[data-callout="sc-vida"] > .callout-title a.internal-link::after,
.callout[data-callout="sc-trabalho"] > .callout-title a.internal-link::after,
.callout[data-callout="sc-projetos"] > .callout-title a.internal-link::after,
.callout[data-callout="sc-conhecimento"] > .callout-title a.internal-link::after,
.callout[data-callout="sc-financeiro"] > .callout-title a.internal-link::after,
.callout[data-callout="sc-planejamento"] > .callout-title a.internal-link::after,
.callout[data-callout="sc-entrada"] > .callout-title a.internal-link::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--sc-raio);
  z-index: 1;
}
.callout[data-callout="sc-vida"] > .callout-content, .callout[data-callout="sc-trabalho"] > .callout-content,
.callout[data-callout="sc-projetos"] > .callout-content, .callout[data-callout="sc-conhecimento"] > .callout-content,
.callout[data-callout="sc-financeiro"] > .callout-content, .callout[data-callout="sc-planejamento"] > .callout-content,
.callout[data-callout="sc-entrada"] > .callout-content {
  color: var(--text-muted);
  font-size: .9em;
  line-height: 1.4;
}

/* ---------- Painéis de seção (fundo suave da área) ---------- */
.callout[data-callout="sc-secao"] { --sc-bg: var(--background-secondary); }
.sc-painel.sc-vida .callout[data-callout="sc-secao"]         { --sc-bg: var(--sc-vida-bg); }
.sc-painel.sc-trabalho .callout[data-callout="sc-secao"]     { --sc-bg: var(--sc-trabalho-bg); }
.sc-painel.sc-projetos .callout[data-callout="sc-secao"]     { --sc-bg: var(--sc-projetos-bg); }
.sc-painel.sc-conhecimento .callout[data-callout="sc-secao"] { --sc-bg: var(--sc-conhecimento-bg); }
.sc-painel.sc-financeiro .callout[data-callout="sc-secao"]   { --sc-bg: var(--sc-financeiro-bg); }
.sc-painel.sc-planejamento .callout[data-callout="sc-secao"] { --sc-bg: var(--sc-planejamento-bg); }
.sc-painel.sc-entrada .callout[data-callout="sc-secao"]      { --sc-bg: var(--sc-entrada-bg); }

/* ---------- Botões de captura e atalhos (links de verdade, com estilo de botão) ---------- */
.callout[data-callout="sc-captura"] { --sc-bg: var(--sc-entrada-bg); }
.callout[data-callout="sc-atalhos"] { --sc-bg: var(--background-secondary); }
.callout[data-callout="sc-captura"] > .callout-content p,
.callout[data-callout="sc-atalhos"] > .callout-content p {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 6px 0 0;
}
.callout[data-callout="sc-captura"] > .callout-content p br,
.callout[data-callout="sc-atalhos"] > .callout-content p br { display: none; }
.callout[data-callout="sc-captura"] a,
.callout[data-callout="sc-atalhos"] a,
.callout[data-callout="sc-secao"] a.external-link {
  display: inline-flex;
  align-items: center;
  padding: 7px 13px;
  border-radius: 999px;
  background: var(--background-primary);
  color: var(--text-normal);
  border: 1px solid var(--background-modifier-border);
  text-decoration: none;
  font-weight: 600;
  font-size: .92em;
  background-image: none;   /* remove o ícone de link externo */
  line-height: 1.2;
  margin: 2px 0;
}
.callout[data-callout="sc-captura"] a:hover,
.callout[data-callout="sc-atalhos"] a:hover,
.callout[data-callout="sc-secao"] a.external-link:hover {
  border-color: var(--interactive-accent);
  color: var(--text-normal);
}

/* ---------- Tabelas dos painéis (Bases) dentro das páginas ---------- */
.sc-painel .internal-embed.bases-embed,
.sc-painel .bases-embed {
  border-radius: 12px;
}

/* ---------- iPhone / telas estreitas ---------- */
@media (max-width: 600px) {
  .callout[data-callout="sc-grade"] > .callout-content {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
  .callout[data-callout="sc-cabecalho"] > .callout-title { font-size: 1.45em; }
  .callout[data-callout="sc-vida"], .callout[data-callout="sc-trabalho"],
  .callout[data-callout="sc-projetos"], .callout[data-callout="sc-conhecimento"],
  .callout[data-callout="sc-financeiro"], .callout[data-callout="sc-planejamento"],
  .callout[data-callout="sc-entrada"] { min-height: 96px; }
}
.is-mobile .callout[data-callout="sc-grade"] > .callout-content {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
